// Public-transit trip planner over each municipality's GTFS index
// (data/transit/<divipola>/network.json, generated by scripts/extract-transit.ts).
// Algorithm: RAPTOR (Delling, Pajor and Werneck, 2012) on scheduled times. Each round allows
// one more bus, so a single run yields both the fastest option and the one with fewest
// transfers. Zero dependencies, same as lib/bogota.mjs.
//
// The JSON output is English (keys and enum values); user-facing strings (`notices`, error
// messages and `tripAsText`) are Spanish because the end users are in Colombia.
import { existsSync, readFileSync } from 'node:fs';

const dataUrl = (f) => new URL(`../data/${f}`, import.meta.url);
const norm = (s) => String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/\s+/g, ' ').trim();

const WALK_MPS = 1.2; // walking speed (m/s)
const DETOUR = 1.25; // streets are not straight lines
const TRANSFER_RADIUS = 400; // meters between stops for a walking transfer
const TRANSFER_MARGIN = 60; // seconds to change buses at the same stop (added when boarding)
const MIN_SAME_STATION = 120; // changing platforms inside a trunk station (tunnel/bridge): ≥ 2 min + margin = 3 min
const STREET_CROSSING = 90; // leaving a station or stop, crossing the road, turnstile/validator
const STATION_RADIUS = 300; // zonal stops around a station that also work to depart/arrive
const MAX_BUSES = 5;
const SAVING_PER_TRANSFER = 240; // an extra transfer is only worth it if it saves 4 min…
const EXTRA_WALK_WEIGHT = 0.5; // …plus half a minute per extra minute walking
const NO_SERVICE_MIN = 30; // if the first bus leaves 30+ min after the requested time, warn
const DAY = 86400;

export const WEEKDAYS = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday'];
// Presentation only: English enums → Spanish labels for the end user
const WEEKDAY_ES = { monday: 'lunes', tuesday: 'martes', wednesday: 'miércoles', thursday: 'jueves', friday: 'viernes', saturday: 'sábado', sunday: 'domingo' };
export const LABEL_ES = { fastest: 'Más rápida', fewest_transfers: 'Menos transbordos', balanced: 'Equilibrada', recommended: 'Recomendada' };
export const dayEs = ({ weekday, holiday }) => (holiday ? 'festivo' : (WEEKDAY_ES[weekday] ?? weekday));

export const sources = () => JSON.parse(readFileSync(dataUrl('transit/sources.json'), 'utf-8')).sources;

// City by name or DIVIPOLA code. Bogotá by default.
export function city(q) {
  const s = sources();
  if (q == null || q === '') return s[0];
  return s.find((x) => x.municipality === String(q).padStart(5, '0') || norm(x.city) === norm(q));
}

export function coverage() {
  return sources().map(({ municipality, city: c, system, publisher, official, license, publish, pending }) => ({
    municipality,
    city: c,
    system,
    publisher,
    official,
    license,
    available: publish && existsSync(dataUrl(`transit/${municipality}/network.json`)),
    ...(pending ? { pending } : {}),
  }));
}

const meters = (a, b) => {
  const dy = (a[2] - b[2]) * 110540;
  const dx = (a[3] - b[3]) * 111320 * Math.cos((a[2] * Math.PI) / 180);
  return Math.hypot(dx, dy);
};
const onFoot = (m) => Math.round((m * DETOUR) / WALK_MPS);

function shortName(name, child) {
  if (!child) return name;
  const h = canon(child.replace(/\s[A-Z]\s*-.*$/, '').replace(/\s(T-?\d.*|Alim.*|Plat.*)$/i, ''));
  if (!h) return name;
  const [first] = name.split(/ [-–] /);
  const cf = canon(first);
  if (first !== name && (cf === h || cf.endsWith(` ${h}`))) return first;
  // No dash ("Universidades CityU"): the first words if they match the platforms
  const words = name.split(' ');
  const n = h.split(' ').length;
  if (n < words.length && canon(words.slice(0, n).join(' ')) === h) return words.slice(0, n).join(' ');
  return name;
}

// Normalized service type from the GTFS agency name (the raw name is kept in `agency`)
export function systemType(agency, routeType) {
  const a = norm(agency);
  if (routeType === 6 || /cable/.test(a)) return 'cable';
  if (/dual/.test(a)) return 'dual';
  if (/alimenta/.test(a)) return 'feeder';
  if (/troncal/.test(a)) return 'trunk';
  if (/complementa/.test(a)) return 'complementary';
  if (/especial/.test(a)) return 'special';
  if (/zonal|urbano|sitp/.test(a)) return 'zonal';
  return 'other';
}

// Compact rows of network.json (see scripts/extract-transit.ts):
// stop  = [stop_id, name, lat, lon, parent_index, stop_code, location_type]
// route = [route_id, short_name, long_name, agency_name, color, route_type]
const networks = {};
export function network(municipality = '11001') {
  if (networks[municipality]) return networks[municipality];
  const file = dataUrl(`transit/${municipality}/network.json`);
  if (!existsSync(file)) return null;
  const r = JSON.parse(readFileSync(file, 'utf-8'));
  const P = r.stops;
  // Patterns serving each stop: flat [patternIndex, position, ...]
  r.atStop = P.map(() => []);
  r.patterns.forEach((p, pi) => p.s.forEach((s, i) => r.atStop[s].push(pi, i)));
  // Walking transfers: ~450 m grid so we do not compare every stop against every stop
  const cell = (p) => `${Math.floor(p[2] / 0.004)},${Math.floor(p[3] / 0.004)}`;
  const grid = new Map();
  P.forEach((p, i) => p[6] === 0 && (grid.get(cell(p)) ?? grid.set(cell(p), []).get(cell(p))).push(i));
  r.near = (lat, lon, radius) => {
    const out = [];
    const cy = Math.floor(lat / 0.004);
    const cx = Math.floor(lon / 0.004);
    const k = Math.ceil(radius / 440);
    for (let y = cy - k; y <= cy + k; y++)
      for (let x = cx - k; x <= cx + k; x++)
        for (const j of grid.get(`${y},${x}`) ?? []) {
          const d = meters([0, 0, lat, lon], P[j]);
          if (d <= radius) out.push([j, d]);
        }
    return out.sort((a, b) => a[1] - b[1]);
  };
  // [neighbor, transfer seconds without the boarding margin, actual walking seconds]
  r.neighbors = P.map((p, i) =>
    p[6] === 0 && r.atStop[i].length
      ? r
          .near(p[2], p[3], TRANSFER_RADIUS)
          .filter(([j]) => j !== i && r.atStop[j].length)
          .map(([j, d]) => {
            const walk = onFoot(d);
            const same = p[4] >= 0 && p[4] === P[j][4];
            return [j, same ? Math.max(MIN_SAME_STATION, walk) : walk + STREET_CROSSING, walk];
          })
      : [],
  );
  // Short name of each station, without sponsorship ("Portal Sur - JFK Coop. Financiera" → "Portal Sur").
  // Only cut when the platforms confirm the part after the dash is commercial
  // ("Suba - Calle 95" stays whole because its platforms say "Suba - Calle 95").
  const firstChild = new Map();
  P.forEach((p) => p[4] >= 0 && !firstChild.has(p[4]) && !isLayover(p) && firstChild.set(p[4], p[1]));
  r.shortNames = P.map((p, i) => (p[6] === 1 ? shortName(p[1], firstChild.get(i)) : p[1]));
  return (networks[municipality] = r);
}

// --- Date and time in Colombia (UTC-5, no daylight saving) ---
function nowColombia() {
  const d = new Date(Date.now() - 5 * 3600e3);
  return { date: d.toISOString().slice(0, 10), time: d.toISOString().slice(11, 16) };
}

function servicesOn(r, date) {
  const ymd = date.replaceAll('-', '');
  const dow = (new Date(`${date}T12:00:00Z`).getUTCDay() + 6) % 7; // monday = 0
  const active = [];
  let holiday = false;
  for (const [id, s] of Object.entries(r.services)) {
    if (s.added.includes(ymd)) holiday = holiday || s.days[dow] === '0';
    const on = s.removed.includes(ymd) ? false : s.added.includes(ymd) ? true : s.days[dow] === '1' && (!s.start || s.start <= ymd) && (!s.end || ymd <= s.end);
    if (on) active.push(id);
  }
  return { active, weekday: WEEKDAYS[dow], holiday };
}

const shiftDate = (date, n) => new Date(Date.parse(`${date}T12:00:00Z`) + n * DAY * 1000).toISOString().slice(0, 10);

// --- Places: coordinates, station, stop code or stop/neighborhood name ---
const isLayover = (p) => /regulaci/i.test(p[1]); // "Regulación" stops are bus layovers, not for riders
// Canonical form to compare names: no accents or punctuation, with Bogotá street-address
// abbreviations expanded ("Av. Jiménez" = "Avenida Jiménez", "C.C. Andino" = "Centro Comercial Andino")
const ABBREV = { av: 'avenida', avda: 'avenida', ak: 'avenida carrera', ac: 'avenida calle', cl: 'calle', cll: 'calle', clle: 'calle', k: 'carrera', kr: 'carrera', kra: 'carrera', cra: 'carrera', cr: 'carrera', dg: 'diagonal', tv: 'transversal', br: 'barrio', hsp: 'hospital', pq: 'parque', est: 'estacion', u: 'universidad', univ: 'universidad', cc: 'centro comercial', eldorado: 'el dorado' };
const canon = (s) =>
  norm(s)
    .replace(/[^a-z0-9]+/g, ' ')
    .replace(/\bc c\b/g, 'cc')
    .replace(/\b(ak|ac|av|cl|cll|kr|cra|k|dg|tv)(\d)/g, '$1 $2')
    .split(' ')
    .map((w) => ABBREV[w] ?? w)
    .join(' ')
    .replace(/\bportal (de la|de las|de los|del|de) /g, 'portal ')
    .trim();
// Station name without sponsorship ("Calle 26 - Atrio" → "calle 26")
const base = (n) => canon(String(n).split(/ [-–] /)[0]);
const noPrefix = (c) => c.replace(/^(barrio|centro comercial|estacion|hospital|parque) /, '');
// Word-start match ("norte" finds "Portal Norte"; "xx" does not find "Juan XXIII")
const atWord = (c, q) => q.length >= 3 && ` ${c} `.includes(` ${q}`);

// Canonical names precomputed per network (canon() over ~8k stops costs ~10 ms per query)
function placeIndex(r, usable) {
  const P = r.stops;
  const children = new Map();
  P.forEach((p, j) => p[4] >= 0 && usable(j) && (children.get(p[4]) ?? children.set(p[4], []).get(p[4])).push(j));
  const names = P.map((p, i) => {
    if (p[6] === 1)
      // Platform short name, without sponsorship: "Universidades A - 4 ó 6" → "universidades"
      return children.has(i) ? { c: canon(p[1]), b: base(p[1]), short: canon(P[children.get(i)[0]][1].replace(/\s[A-Z]\s*-.*$/, '')) } : null;
    return p[4] < 0 && usable(i) ? { c: canon(p[1]), codes: [norm(p[5]).replace(/_tm$/, ''), norm(p[0])] } : null;
  });
  return { children, names };
}

export function resolvePlace(r, q) {
  const text = String(q ?? '').trim();
  if (!text) throw new Error('Falta el lugar (nombre de estación, parada o "lat,lon")');
  const P = r.stops;
  const m = /^(-?\d{1,2}(?:\.\d+)?)(?:\s*[,;]\s*|\s+)(-?\d{1,3}(?:\.\d+)?)$/.exec(text);
  if (m && Math.abs(+m[1]) <= 90 && Math.abs(+m[2]) <= 180 && (m[1].includes('.') || m[2].includes('.'))) {
    const [lat, lon] = [+m[1], +m[2]];
    let c = r.near(lat, lon, 700).filter(([j]) => r.atStop[j].length && !isLayover(P[j]));
    if (!c.length) c = r.near(lat, lon, 1500).filter(([j]) => r.atStop[j].length && !isLayover(P[j]));
    if (!c.length) throw new Error(`No hay paradas a menos de 1,5 km de ${text}`);
    return { name: text, label: `Cerca de ${platform(r, c[0][0]).short_name}`, lat, lon, stops: c.slice(0, 40).map(([j, d]) => [j, onFoot(d)]) };
  }
  const q2 = canon(text);
  const qCode = norm(text).replace(/_tm$/, '');
  const usable = (j) => r.atStop[j].length && !isLayover(P[j]);
  const { children, names } = (r.placeIndex ??= placeIndex(r, usable));

  // Candidates with their match level (lower = better)
  const cand = [];
  P.forEach((p, i) => {
    const x = names[i];
    if (!x) return;
    const { c } = x;
    if (p[6] === 1) {
      const { b, short } = x;
      const level = c === q2 || b === q2 || short === q2 ? 1 : atWord(c, q2) || atWord(short, q2) ? 2 : 0;
      if (level) cand.push({ i, level, station: true, c });
    } else {
      const byCode = x.codes.includes(qCode);
      const level = byCode ? 0 : c === q2 ? 1.5 : noPrefix(c) === noPrefix(q2) ? 1.6 : atWord(c, q2) ? 3 : -1;
      if (level >= 0) cand.push({ i, level, station: false, c });
    }
  });
  if (!cand.length) throw new Error(`No encontré "${text}". Prueba con el nombre de una estación, una parada o coordenadas "lat,lon".`);
  // At equal level: station first, then the shortest name. A portal containing the word beats
  // the other stations ("Suba" → Portal Suba, not Suba - Calle 95), with the others as suggestions.
  const lv = (x) => (x.station && x.level <= 2 && x.c.startsWith('portal ') && !q2.startsWith('portal') ? 0.9 : x.level);
  cand.sort((a, b) => lv(a) - lv(b) || b.station - a.station || P[a.i][1].length - P[b.i][1].length);
  const chosen = cand[0];
  const pc = P[chosen.i];

  // Suggestions: other places that also match and are far from the chosen one
  const suggestions = [];
  if (chosen.level > 1.6 || lv(chosen) < chosen.level || cand.some((x) => x !== chosen && x.level <= 1.6 && meters(P[x.i], pc) > 1000)) {
    const seen = [pc];
    for (const x of cand.slice(1)) {
      const p = P[x.i];
      if (x.level > chosen.level + 2 || seen.some((v) => meters(v, p) < 600 && (canon(v[1]) === x.c || meters(v, p) < 250))) continue;
      seen.push(p);
      suggestions.push({ name: p[1], type: x.station ? 'station' : 'stop', ...(p[5] && !x.station ? { code: p[5] } : {}), lat: p[2], lon: p[3] });
      if (suggestions.length === 5) break;
    }
  }
  const extra = suggestions.length ? { suggestions } : {};

  if (chosen.station) {
    // Station platforms + zonal stops at the exit (cross the street and enter/leave the station)
    const ps = children.get(chosen.i).map((j) => [j, 0]);
    const inside = new Set(ps.map(([j]) => j));
    for (const [j, d] of r.near(pc[2], pc[3], STATION_RADIUS)) if (!inside.has(j) && usable(j)) ps.push([j, onFoot(d) + STREET_CROSSING]);
    return { name: pc[1], label: r.shortNames[chosen.i], lat: pc[2], lon: pc[3], stops: ps, ...extra };
  }
  const c = r.near(pc[2], pc[3], 250).filter(([j]) => usable(j));
  return { name: pc[1], label: pc[1], lat: pc[2], lon: pc[3], ...(pc[5] ? { code: pc[5] } : {}), stops: c.map(([j, d]) => [j, onFoot(d)]), ...extra };
}

// --- Departures of a pattern on a day: fixed times + frequencies (TransMiCable) ---
// `yesterday` = previous day's services: their after-midnight trips (GTFS 24:xx, 25:xx) are
// moved to the requested day by subtracting 24 h, so a 00:30 query sees them.
function departures(r, pi, day, cache) {
  if (cache.has(pi)) return cache.get(pi);
  const p = r.patterns[pi];
  const fmax = p.f ? Math.max(1, ...p.f) : 1;
  const fixed = day.active.flatMap((s) => p.v[s] ?? []);
  const fq = day.active.flatMap((s) => p.fq?.[s] ?? []);
  if (day.yesterday) {
    const dur = p.t.at(-1) * fmax;
    for (const s of day.yesterday) {
      for (const x of p.v[s] ?? []) if (x + dur >= DAY) fixed.push(x - DAY);
      for (const [a, b, h] of p.fq?.[s] ?? []) if (b + p.t.at(-1) > DAY) fq.push([a - DAY, b - DAY, h]);
    }
  }
  fixed.sort((a, b) => a - b);
  const out = { fixed, fq, fmax };
  cache.set(pi, out);
  return out;
}

const factor = (p, start) => (p.f ? (p.f[Math.floor(Math.max(0, start) / 3600)] ?? 1) : 1);

// Pattern trip that reaches position i first, from `from` (seconds of the day).
// The hourly factor lets one trip overtake another (non-FIFO), so several are checked.
function firstTrip(r, pi, i, from, dep) {
  const p = r.patterns[pi];
  let best = null;
  const { fixed, fq, fmax } = dep;
  let lo = 0;
  let hi = fixed.length;
  const limit = from - p.t[i] * fmax; // no trip departing before this can pass after `from`
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (fixed[mid] < limit) lo = mid + 1;
    else hi = mid;
  }
  for (let k = lo, seen = 0; k < fixed.length && seen < 4; k++) {
    const f = factor(p, fixed[k]);
    const passes = fixed[k] + p.t[i] * f;
    if (passes < from) continue;
    seen++;
    if (!best || passes < best.passes) best = { start: fixed[k], f, passes };
  }
  for (const [a, b, h] of fq) {
    const start = Math.max(a, a + Math.ceil((from - p.t[i] - a) / h) * h);
    if (start >= b) continue;
    const passes = start + p.t[i];
    if (!best || passes < best.passes) best = { start, f: 1, passes };
  }
  return best;
}

// RAPTOR. tau[k][s] = best time at s with ≤ k buses (on board or walking); `byBus[k]` keeps only
// the bus arrivals of round k: walking transfers and the arrival at the destination start from
// there, so two walks are never chained (bus → walk → walk).
function raptor(r, origin, destination, t0, day) {
  const N = r.stops.length;
  const tau = [new Float64Array(N).fill(Infinity)];
  const labels = [new Map()];
  const byBus = [new Map()];
  const best = new Float64Array(N).fill(Infinity);
  const bestBus = new Float64Array(N).fill(Infinity);
  let marked = new Set();
  for (const [s, w] of origin.stops) {
    if (t0 + w < tau[0][s]) {
      tau[0][s] = best[s] = t0 + w;
      labels[0].set(s, { type: 'access', w });
      marked.add(s);
    }
  }
  const egress = new Map();
  for (const [s, w] of destination.stops) if (!(egress.get(s) <= w)) egress.set(s, w);
  let bound = Infinity;
  const cache = new Map();
  const rounds = [];
  for (let k = 1; k <= MAX_BUSES && marked.size; k++) {
    tau[k] = tau[k - 1].slice();
    labels[k] = new Map();
    byBus[k] = new Map();
    const queue = new Map();
    for (const s of marked) {
      const list = r.atStop[s];
      for (let j = 0; j < list.length; j += 2) {
        const pi = list[j];
        const pos = list[j + 1];
        if (!queue.has(pi) || pos < queue.get(pi)) queue.set(pi, pos);
      }
    }
    const next = new Set();
    for (const [pi, pos0] of queue) {
      const p = r.patterns[pi];
      const dep = departures(r, pi, day, cache);
      let trip = null;
      let boardAt = -1;
      for (let i = pos0; i < p.s.length; i++) {
        const s = p.s[i];
        if (trip) {
          const arr = trip.start + p.t[i] * trip.f;
          if (arr < bestBus[s] && arr < bound) {
            const L = { type: 'bus', pi, start: trip.start, f: trip.f, i0: boardAt, i1: i, arrives: arr };
            bestBus[s] = arr;
            byBus[k].set(s, L);
            if (arr < best[s]) {
              tau[k][s] = best[s] = arr;
              labels[k].set(s, L);
              next.add(s);
            }
          }
        }
        // Board with what the previous round achieved (tau[k-1]); round 1 starts from the walking access
        const prev = tau[k - 1][s];
        if (prev === Infinity) continue;
        const ready = prev + (k === 1 ? 0 : TRANSFER_MARGIN);
        const current = trip ? trip.start + p.t[i] * trip.f : Infinity;
        if (ready <= current) {
          const other = firstTrip(r, pi, i, ready, dep);
          if (other && other.passes < current) {
            trip = other;
            boardAt = i;
          }
        }
      }
    }
    // Walking transfers, only from this round's bus arrivals
    for (const [s, bus] of byBus[k]) {
      for (const [n, w, walk] of r.neighbors[s]) {
        const arr = bus.arrives + w;
        if (arr < best[n] && arr < bound) {
          tau[k][n] = best[n] = arr;
          labels[k].set(n, { type: 'walk', from: s, w, walk, bus });
          next.add(n);
        }
      }
    }
    marked = next;
    let top = Infinity;
    let e = -1;
    for (const [s, w] of egress) {
      const L = byBus[k].get(s);
      if (L && L.arrives + w < top) (top = L.arrives + w), (e = s);
    }
    if (e >= 0 && top < bound) {
      bound = top;
      rounds.push({ k, e, arrival: top });
    }
  }
  return { tau, labels, byBus, rounds, egress };
}

const hhmm = (s) => {
  const m = Math.round(s / 60);
  return `${String(Math.floor(m / 60) % 24).padStart(2, '0')}:${String(m % 60).padStart(2, '0')}`;
};
const minutes = (s) => Math.max(1, Math.round(s / 60));

// "Calle 72 A - 2" → car A, door 2 (trunk-station platform naming convention)
function platform(r, s) {
  const p = r.stops[s];
  const parent = p[4] >= 0 ? r.stops[p[4]] : null;
  const m = /\s([A-Z])\s*-\s*(\d+(?:\s*ó\s*\d+)?)\.?$/.exec(p[1]);
  const stop = parent ? parent[1] : p[1];
  return {
    stop,
    short_name: parent ? r.shortNames[p[4]] : stop,
    ...(m ? { car: m[1], door: m[2].replace(/\s+/g, ' ') } : parent ? { platform: p[1] } : {}),
    ...(p[5] && p[5] !== p[1] ? { code: p[5] } : {}),
    lat: p[2],
    lon: p[3],
  };
}

// Bus headsign. On loop routes (ends where it started: TransMiCable, feeders) the final
// destination is the origin itself, so while outbound the turnaround point is shown.
function headsign(r, p, i1 = 0, short = false) {
  const name = (j) => platform(r, p.s[j])[short ? 'short_name' : 'stop'];
  const n = p.s.length;
  if (n > 2 && name(0) === name(n - 1) && i1 < Math.floor((n - 1) / 2) + 1) return name(Math.floor((n - 1) / 2));
  return name(n - 1);
}

function rebuild(r, res, k, e, t0, origin, destination) {
  const legs = [];
  let s = e;
  const labelAt = (k, s) => {
    for (let j = k; j >= 0; j--) if (res.labels[j].has(s)) return [j, res.labels[j].get(s)];
    return [-1, null];
  };
  let round = k;
  let forced = res.byBus[k].get(e); // the destination is always reached by bus (then walk)
  for (let guard = 0; guard < 50; guard++) {
    const [j, L] = forced ? [round, forced] : labelAt(round, s);
    forced = null;
    if (!L) break;
    round = j;
    if (L.type === 'access') {
      if (L.w > 30) legs.unshift({ type: 'walk', from: origin.name, to: platform(r, s).stop, min: minutes(L.w) });
      break;
    }
    if (L.type === 'walk') {
      const [a, b] = [platform(r, L.from), platform(r, s)];
      const same = r.stops[L.from][4] >= 0 && r.stops[L.from][4] === r.stops[s][4];
      legs.unshift({ type: 'walk', from: a.stop, to: b.stop, min: minutes(L.w), transfer: true, ...(same ? { same_station: true } : {}) });
      s = L.from;
      forced = L.bus;
      continue;
    }
    const p = r.patterns[L.pi];
    const route = r.routes[p.r];
    const departs = L.start + p.t[L.i0] * L.f;
    const arrives = L.start + p.t[L.i1] * L.f;
    legs.unshift({
      type: 'ride',
      route: route[1],
      route_name: route[2],
      agency: route[3],
      system: systemType(route[3], route[5]),
      color: `#${route[4]}`,
      headsign: headsign(r, p, L.i1),
      headsign_short: headsign(r, p, L.i1, true),
      board: platform(r, p.s[L.i0]),
      alight: platform(r, p.s[L.i1]),
      departs: hhmm(departs),
      arrives: hhmm(arrives),
      stops: L.i1 - L.i0,
      min: minutes(arrives - departs),
      _departs: departs,
    });
    s = p.s[L.i0];
    round = j - 1;
  }
  // Transfer at the same stop: explicit 0-min leg so the UI can draw it
  for (let i = legs.length - 1; i > 0; i--)
    if (legs[i].type === 'ride' && legs[i - 1].type === 'ride')
      legs.splice(i, 0, { type: 'walk', from: legs[i].board.stop, to: legs[i].board.stop, min: 0, transfer: true, same_stop: true });
  const egress = res.egress.get(e) ?? 0;
  const last = res.byBus[k].get(e).arrives;
  // Egress under 30 s is not shown: the arrival is then the bus arrival (not 1 min later)
  if (egress > 30) legs.push({ type: 'walk', from: platform(r, e).stop, to: destination.name, min: minutes(egress) });
  const arrival = last + (egress > 30 ? egress : 0);
  // Departure time: just in time for the first bus (no extra waiting at the stop)
  const first = legs.findIndex((t) => t.type === 'ride');
  const before = legs.slice(0, Math.max(first, 0)).reduce((a, t) => a + t.min * 60, 0);
  const leave = first >= 0 ? Math.max(t0, legs[first]._departs - before) : t0;
  // Waits: between reaching the stop and the bus departure
  let clock = leave;
  for (const t of legs) {
    if (t.type === 'walk') clock += t.min * 60;
    else {
      t.wait_min = Math.max(0, Math.round((t._departs - clock) / 60));
      clock = t._departs + t.min * 60;
      delete t._departs;
    }
  }
  return { legs, leave, arrival };
}

// Options of one RAPTOR run. Pareto with tolerance: one more bus only makes it in if it saves
// SAVING_PER_TRANSFER plus EXTRA_WALK_WEIGHT per extra second walking.
function optionsFrom(r, res, t0, o, d) {
  const all = res.rounds.map(({ k, e }) => {
    const { legs, leave, arrival } = rebuild(r, res, k, e, t0, o, d);
    const rides = legs.filter((t) => t.type === 'ride');
    return {
      departs: hhmm(leave),
      arrives: hhmm(arrival),
      duration_min: minutes(arrival - leave),
      transfers: rides.length - 1,
      walk_min: legs.filter((t) => t.type === 'walk').reduce((a, t) => a + t.min, 0),
      wait_min: rides.reduce((a, t) => a + t.wait_min, 0),
      legs,
      _arrives: arrival,
      _departs: leave,
    };
  });
  const kept = [];
  for (const x of all) {
    const prev = kept.at(-1);
    if (!prev || x._arrives <= prev._arrives - SAVING_PER_TRANSFER - EXTRA_WALK_WEIGHT * 60 * Math.max(0, x.walk_min - prev.walk_min)) kept.push(x);
  }
  // The one we recommend: arrive earlier, but each transfer "costs" 4 min and walking a quarter
  const cost = (x) => x._arrives + SAVING_PER_TRANSFER * x.transfers + 15 * x.walk_min;
  const rec = kept.reduce((a, x) => (a && cost(a) <= cost(x) ? a : x), null);
  // Key order: label and recommended first, then the times
  return kept.map((op, i) => ({
    label: kept.length === 1 ? 'recommended' : i === 0 ? 'fewest_transfers' : i === kept.length - 1 ? 'fastest' : 'balanced',
    recommended: op === rec,
    ...op,
  }));
}

/**
 * Plans a trip. Returns Pareto options (fastest ↔ fewest transfers).
 * If there is no service at that time, finds the first departure of the following days (`no_service`).
 * @param {{origin:string,destination:string,time?:string,date?:string,city?:string}} q
 */
export function planTrip(q = {}) {
  // Bounded inputs: the MCP and /api/tools do not trim, and names > 200 characters do not exist
  const cut = (x) => (x == null ? x : String(x).slice(0, 200));
  let { origin, destination, time, date, city: c } = Object.fromEntries(['origin', 'destination', 'time', 'date', 'city'].map((k) => [k, cut(q[k])]));
  const src = city(c);
  if (!src) throw new Error(`Ciudad no reconocida: ${c}. Ver transit_coverage.`);
  const r = network(src.municipality);
  if (!r) throw new Error(`${src.city} aún no tiene red publicada${src.pending ? `: ${src.pending}` : ''}`);
  const now = nowColombia();
  date ||= now.date;
  time ||= now.time;
  // Round-trip through Date: rejects 2026-02-31 (Date.parse rolls it into March)
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date) || new Date(`${date}T12:00:00Z`).toISOString?.().slice(0, 10) !== date) throw new Error('La fecha (date) debe ser AAAA-MM-DD');
  const ymd = date.replaceAll('-', '');
  const { start, end } = r.feed ?? {};
  const iso = (x) => `${x.slice(0, 4)}-${x.slice(4, 6)}-${x.slice(6)}`;
  if (start && end && (ymd < start || ymd > end)) throw new Error(`Hay horarios del ${iso(start)} al ${iso(end)}; ${date} está fuera de la vigencia del feed.`);
  const mh = /^(\d{1,2}):(\d{2})$/.exec(time);
  if (!mh || +mh[1] > 23 || +mh[2] > 59) throw new Error('La hora (time) debe ser HH:MM');
  time = `${mh[1].padStart(2, '0')}:${mh[2]}`;
  const t0 = +mh[1] * 3600 + +mh[2] * 60;
  const o = resolvePlace(r, origin);
  const d = resolvePlace(r, destination);
  const today = servicesOn(r, date);
  // Before 4 a.m. the previous day's trips are still running (GTFS 24:xx hours)
  const yesterday = t0 < 4 * 3600 ? servicesOn(r, shiftDate(date, -1)).active : null;
  let options = optionsFrom(r, raptor(r, o, d, t0, { active: today.active, yesterday }), t0, o, d);
  const notices = ['Horarios programados del GTFS oficial: no hay datos en tiempo real de buses en Colombia.'];
  let noService = null;
  // Nothing from that time: first departure of the next days (Sunday/holiday → weekday can skip two days)
  for (let n = 1; n <= 3 && !options.length; n++) {
    const other = shiftDate(date, n);
    if (end && other.replaceAll('-', '') > end) break;
    const nextDay = servicesOn(r, other);
    const ops = optionsFrom(r, raptor(r, o, d, 0, { active: nextDay.active, yesterday: null }), 0, o, d);
    if (ops.length) {
      options = ops.map((op) => ({ ...op, date: other }));
      const first = hhmm(Math.min(...options.map((x) => x._departs)));
      noService = { time, resumes: { date: other, time: first, weekday: nextDay.weekday, holiday: nextDay.holiday } };
      notices.unshift(`No hay salidas para este viaje desde las ${time} del ${dayEs(today)} ${date}. La próxima es el ${dayEs(nextDay)} ${other} a las ${first}.`);
    }
  }
  if (!noService && options.length) {
    const first = Math.min(...options.map((x) => x._departs));
    if (first - t0 >= NO_SERVICE_MIN * 60) {
      noService = { time, resumes: { date, time: hhmm(first), weekday: today.weekday, holiday: today.holiday } };
      notices.unshift(`A las ${time} aún no hay servicio para este viaje: la primera salida es a las ${hhmm(first)}.`);
    }
  }
  const direct = meters([0, 0, o.lat, o.lon], [0, 0, d.lat, d.lon]);
  if (!options.length && direct >= 300) notices.unshift(`No encontré un viaje con hasta ${MAX_BUSES} buses saliendo a las ${time} ni en los 3 días siguientes. Prueba un lugar cercano o con coordenadas.`);
  for (const op of options) delete op._arrives, delete op._departs;
  for (const [x, raw] of [[o, origin], [d, destination]])
    if (x.suggestions) notices.push(`"${raw}" coincide con varios lugares; usé ${x.name}. Si no era, prueba: ${x.suggestions.map((s) => (s.name === x.name && s.code ? `${s.name} (${s.code})` : s.name)).join(', ')}.`);
  if (!r.official) notices.push('Feed comunitario, no oficial: los horarios pueden estar desactualizados.');
  // Walking can beat everything on short trips
  const walk = direct < 2000 ? { walk_only_min: minutes(onFoot(direct)) } : {};
  // Origin = destination or one block away: no buses (walking time is already in walk_only_min).
  // ponytail: buses slower than walking are not dropped; at night or with luggage the bus is still an option.
  if (direct < 300) {
    options = [];
    noService = null;
    notices.unshift(`Están a ~${Math.round(direct)} m: camina (~${walk.walk_only_min} min).`);
  }
  const place = (x) => ({ name: x.name, label: x.label, lat: x.lat, lon: x.lon, ...(x.code ? { code: x.code } : {}) });
  const suggestions = o.suggestions || d.suggestions ? { suggestions: { ...(o.suggestions ? { origin: o.suggestions } : {}), ...(d.suggestions ? { destination: d.suggestions } : {}) } } : {};
  return {
    city: r.city,
    municipality: r.municipality,
    origin: place(o),
    destination: place(d),
    date,
    time,
    weekday: today.weekday,
    holiday: today.holiday,
    options,
    ...walk,
    ...(noService ? { no_service: noService } : {}),
    ...suggestions,
    notices,
    source: { publisher: r.publisher, license: r.license, file: r.source, generated: r.generated, validity: r.feed },
  };
}

// Searchable names that do resolve (for autocomplete): stations by their short name and the
// stops/neighborhoods with the most routes, without repeated names. Computed once per network.
export function suggestedPlaces(c, limit = 400) {
  const src = city(c);
  const r = src && network(src.municipality);
  if (!r) return [];
  if (r.suggested) return r.suggested.slice(0, limit);
  const P = r.stops;
  const seen = new Set();
  const out = [];
  const add = (n) => {
    const k = canon(n);
    if (!k || seen.has(k)) return;
    seen.add(k);
    out.push(n);
  };
  const withRoutes = new Set();
  P.forEach((p, i) => p[4] >= 0 && r.atStop[i].length && withRoutes.add(p[4]));
  P.forEach((p, i) => p[6] === 1 && withRoutes.has(i) && add(r.shortNames[i]));
  const zonal = P.map((p, i) => [p, r.atStop[i].length]).filter(([p, n]) => p[6] === 0 && p[4] < 0 && n && !isLayover(p) && !/_/.test(p[1]));
  const byName = new Map();
  for (const [p, n] of zonal) byName.set(p[1], (byName.get(p[1]) ?? 0) + n);
  for (const [n] of [...byName].sort((a, b) => b[1] - a[1])) add(n);
  r.suggested = out; // all come from stops with routes, so resolvePlace finds them (see test)
  return out.slice(0, limit);
}

// Stops near a point with the routes that serve them ("what works for me here?")
export function nearbyStops({ lat, lon, radius = 400, city: c, limit = 10 } = {}) {
  limit = Math.min(Math.max(1, Math.floor(+limit) || 10), 50);
  const src = city(c);
  const r = src && network(src.municipality);
  if (!r) throw new Error('Ciudad sin red publicada. Ver transit_coverage.');
  if (!Number.isFinite(+lat) || !Number.isFinite(+lon)) throw new Error('lat y lon son obligatorios');
  return r
    .near(+lat, +lon, Math.min(+radius || 400, 2000))
    .filter(([j]) => r.atStop[j].length)
    .slice(0, limit)
    .map(([j, dm]) => {
      const routes = new Set();
      for (let k = 0; k < r.atStop[j].length; k += 2) routes.add(r.routes[r.patterns[r.atStop[j][k]].r][1]);
      return { ...platform(r, j), distance_m: Math.round(dm), walk_min: minutes(onFoot(dm)), routes: [...routes].sort() };
    });
}

// Route stops in order for each pattern (direction/variant)
export function routeStops({ route, city: c } = {}) {
  const src = city(c);
  const r = src && network(src.municipality);
  if (!r) throw new Error('Ciudad sin red publicada. Ver transit_coverage.');
  const q = norm(route);
  const ids = new Set(r.routes.map((x, i) => [x, i]).filter(([x]) => norm(x[1]) === q || norm(x[0]) === q).map(([, i]) => i));
  if (!ids.size) throw new Error(`Ruta no encontrada: ${route}`);
  return r.patterns
    .filter((p) => ids.has(p.r))
    .map((p) => {
      const x = r.routes[p.r];
      const trips = Object.values(p.v).reduce((a, v) => a + v.length, 0);
      return {
        route: x[1],
        route_name: x[2],
        agency: x[3],
        system: systemType(x[3], x[5]),
        headsign: headsign(r, p),
        duration_min: minutes(p.t.at(-1)),
        scheduled_trips: trips,
        stops: p.s.map((s, i) => ({ ...platform(r, s), min: Math.round(p.t[i] / 60) })),
      };
    })
    .sort((a, b) => b.scheduled_trips - a.scheduled_trips);
}

// Plain text for chat bots (WhatsApp, Telegram, Grok...). Spanish: it goes straight to the rider.
export function tripAsText(v) {
  const where = (x) => `${x.stop}${x.car ? ` (vagón ${x.car}, puerta ${x.door})` : x.platform ? ` (${x.platform})` : ''}`;
  const out = [`🚌 ${v.origin.name} → ${v.destination.name} · ${dayEs(v)} ${v.date} ${v.time}`];
  v.options.forEach((op, i) => {
    out.push('', `${i + 1}. ${LABEL_ES[op.label] ?? op.label}: sal${op.date ? ` el ${op.date}` : ''} a las ${op.departs}, llegas ${op.arrives} (${op.duration_min} min, ${op.transfers} transbordo${op.transfers === 1 ? '' : 's'}, ${op.walk_min} min a pie)`);
    for (const t of op.legs) {
      if (t.same_stop) out.push(`   🔁 Cambia de bus en ${t.to}`);
      else if (t.type === 'walk') out.push(t.same_station ? `   🔁 Cambia de vagón en ${t.to} (${t.min} min)` : t.transfer && t.from === t.to ? `   🚶 Cruza a la otra parada ${t.to} (${t.min} min)` : `   🚶 Camina ${t.min} min a ${t.to}`);
      else out.push(`   🚍 ${t.route} hacia ${t.headsign}: sube en ${where(t.board)} ${t.departs}${t.wait_min ? ` (esperas ~${t.wait_min} min)` : ''}, baja en ${where(t.alight)} ${t.arrives} · ${t.stops} paradas`);
    }
  });
  if (v.walk_only_min) out.push('', `🚶 A pie directo: ~${v.walk_only_min} min.`);
  out.push('', ...v.notices.map((a) => `ℹ️ ${a}`), `Datos: ${v.source.publisher}, ${v.source.license ?? 'licencia no declarada'}.`);
  return out.join('\n');
}
